const root=document.querySelector('#app');
let chatViewport=null,enterprisePage=null;
function disposeEnterprise(){enterprisePage?.destroy();enterprisePage=null;document.querySelector('.app-shell')?.classList.remove('enterprise-mode');}
function renderEnterprise(tab){
  const shell=document.querySelector('.app-shell');shell?.classList.add('enterprise-mode');
  if(enterprisePage?.tab===tab&&enterprisePage.page.isConnected)return;
  enterprisePage?.destroy();chatViewport?.destroy();chatViewport=null;const ticket=sessionTicket();
  enterprisePage=createEnterprisePage({host:document.querySelector('.workspace'),tab,api,post,notify,openCollaboration:name=>{if(!closeFeature())return;if(name==='moments')loadMoments().catch(error=>notify(error.message));else if(name==='favorites')favoritesPage().catch(error=>notify(error.message));else if(name==='my-code')showMyCode(state.user,{notify});else if(name==='scan-code'){const scanTicket=sessionTicket();scanCode({notify,onUser:username=>{if(sameSession(scanTicket))addFriendDialog(username);}}).catch(error=>notify(error.message));}},getSession:()=>({base:apiBase,token:state.token,user:state.user}),isCurrent:()=>sameSession(ticket)});
}
const query=new URLSearchParams(location.search);
const demoIdentity=['lin','chen'].includes(query.get('demo'))?query.get('demo'):null;
const sessionKey='ichat.session'+(demoIdentity?'.demo.'+demoIdentity:'');
