function renderEmpty(){chatViewport?.destroy();chatViewport=null;const pane=document.querySelector('#chat-pane');if(!pane)return;pane.className='chat-pane empty';pane.innerHTML=`<div class="empty-chat"><span class="brand-mark" aria-hidden="true"><img src="./assets/brand-flower.png" alt="" width="51" height="51"></span><h2>小紫在，好友就在</h2><p>发段文字、分享照片，或和大家一起聊。</p><button class="button secondary" data-action="add-friend">${icon('plus')} 添加一位朋友</button></div>`;}
