async function openContact(id){try{const {conversation}=await post('/api/conversations',{userId:id});await refreshConversations();state.tab='chats';state.query='';renderSidebar();await openConversation(conversation.id);}catch(error){notify(error.message);}}
async function sendMessage(event){
  event.preventDefault();const input=document.querySelector('#message-input'),text=input?.value.trim(),id=state.activeId;if(!text||!id||state.sending)return;const replyToId=state.replyTo?.id;
  const ticket=sessionTicket(),pending=state.pendingDraft?.body===text&&state.pendingDraft?.conversationId===id&&state.pendingDraft?.replyToId===replyToId?state.pendingDraft:{clientId:uid(),body:text,conversationId:id,replyToId};state.pendingDraft=pending;state.sending=true;const button=document.querySelector('#send-button');button.disabled=true;
  try{const {message}=await post(`/api/conversations/${id}/messages`,{body:text,clientId:pending.clientId,...(replyToId?{replyToId}: {})});assertSession(ticket);state.pendingDraft=null;if(state.activeId===id){mergeMessages([message]);renderMessages();const currentInput=document.querySelector('#message-input');if(currentInput?.value.trim()===text)currentInput.value='';if(state.replyTo?.id===replyToId)state.replyTo=null;saveComposerDraft();renderReplyComposer();await markRead(id);}else{const saved=state.drafts.get(id);if(saved?.body.trim()===text&&saved.replyTo?.id===replyToId)state.drafts.delete(id);}await refreshConversations();}catch(error){if(sameSession(ticket))notify(error.message);}finally{if(sameSession(ticket))state.sending=false;if(button.isConnected)button.disabled=false;}
}
