const featureDialog=document.createElement('dialog');featureDialog.id='feature-dialog';document.body.append(featureDialog);
const imageDialog=document.createElement('dialog');imageDialog.id='image-dialog';imageDialog.innerHTML='<button class="image-close icon-button" data-action="close-image" aria-label="关闭照片">'+icon('close')+'</button><img alt="聊天照片">';document.body.append(imageDialog);
function openDialog(title,html,wide=false){
  if(featureDialog.open&&!dialogSubmitting&&dialogIsDirty()&&!window.confirm('内容尚未保存，确认放弃这次编辑？'))throw Error('已保留未保存的内容');
  disposeVoice();dialogSubmitting=false;featureDialog.dataset.section='';dialogEpoch++;featureDialog.classList.toggle('wide-dialog',wide);featureDialog.innerHTML=`<div class="modal-heading"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div>${html}`;if(!featureDialog.open)featureDialog.showModal();hydrateMedia(featureDialog);return dialogEpoch;
}
function formHandler(action){
  const form=featureDialog.querySelector('form');if(!form)return;form.dataset.initial=formSnapshot(form);
  form.addEventListener('submit',async event=>{
    event.preventDefault();if(form.dataset.busy==='1')return;const blocking=!form.dataset.transient;if(blocking&&dialogSubmitting)return;
    const button=form.querySelector('[type=submit]'),ticket=sessionTicket(),stamp=dialogEpoch;form.dataset.busy='1';if(button)button.disabled=true;if(blocking)dialogSubmitting=true;
    const error=form.querySelector('.form-error');if(error)error.textContent='';
    try{await action(new FormData(form));assertSession(ticket);if(form.isConnected&&stamp===dialogEpoch)form.dataset.initial=formSnapshot(form);}
    catch(err){if(!sameSession(ticket)||stamp!==dialogEpoch)return;if(error?.isConnected)error.textContent=err.message;else notify(err.message);}
    finally{form.dataset.busy='';if(sameSession(ticket)&&stamp===dialogEpoch&&blocking)dialogSubmitting=false;if(button?.isConnected)button.disabled=false;}
  });
}
