async function groupInfo(id=state.activeId){
  const ticket=sessionTicket(),stamp=dialogEpoch,info=await api('/api/groups/'+id);assertSession(ticket);if(stamp!==dialogEpoch)return;const c=info.conversation,owner=c.ownerId===state.user.id,myRole=info.members.find(u=>u.id===state.user.id)?.role,manager=owner||myRole==='admin';
  openDialog('群聊资料',`<div class="group-summary">${chatAvatar(c)}<h3>${esc(chatTitle(c))}</h3><p>${info.members.length} 位成员</p></div><section class="group-announcement"><b>群公告</b><p>${esc(info.announcement||c.announcement||'还没有群公告')}</p></section><div class="group-members enhanced-members">${info.members.map(u=>`<div>${avatar(u)}<span>${esc(u.groupAlias||u.displayName)}</span>${u.groupAlias?`<small>${esc(u.displayName)}</small>`:''}<small>${{owner:'群主',admin:'管理员',member:''}[u.role]||''}</small>${owner&&u.id!==state.user.id?`<button class="text-button" data-action="group-admin" data-group="${esc(id)}" data-id="${esc(u.id)}" data-enabled="${u.role==='admin'?'false':'true'}">${u.role==='admin'?'取消管理':'设为管理'}</button><button class="text-button" data-action="group-transfer" data-group="${esc(id)}" data-id="${esc(u.id)}" data-name="${esc(u.displayName)}">转让群主</button>`:''}${u.id!==state.user.id&&u.role!=='owner'&&(owner||(manager&&u.role!=='admin'))?`<button class="text-button danger-text" data-action="remove-member" data-group="${esc(id)}" data-id="${esc(u.id)}" data-name="${esc(u.displayName)}">移出</button>`:''}</div>`).join('')}</div><div class="group-actions"><button class="button secondary" data-action="invite-members" data-group="${esc(id)}">${icon('plus')} 邀请好友</button><button class="button secondary" data-action="group-alias" data-group="${esc(id)}">群内昵称</button>${manager?`<button class="button secondary" data-action="edit-group" data-group="${esc(id)}">${icon('edit')} 群资料与公告</button>`:''}<button class="text-button danger-text" data-action="leave-group" data-group="${esc(id)}">退出群聊</button>${owner?`<button class="text-button danger-text" data-action="dissolve-group" data-group="${esc(id)}">解散群聊</button>`:''}</div>`,true);
}
async function inviteDialog(id){const stamp=dialogEpoch;const [{members},contacts]=await Promise.all([api('/api/groups/'+id),api('/api/contacts')]);if(stamp!==dialogEpoch)return;const existing=new Set(members.map(u=>u.id));openDialog('邀请好友入群',`<form>${friendChoices(contacts.users.filter(u=>!u.blocked&&!existing.has(u.id)))}${dialogActions('邀请入群')}</form>`,true);formHandler(async data=>{const userIds=data.getAll('userIds');if(!userIds.length)throw Error('请选择要邀请的好友');await post('/api/groups/'+id+'/members',{userIds});await refreshConversations();await groupInfo(id);notify('好友已加入群聊');});}
async function editGroupDialog(id){const ticket=sessionTicket(),stamp=dialogEpoch,info=await api('/api/groups/'+id);assertSession(ticket);if(stamp!==dialogEpoch)return;const c=info.conversation;openDialog('群资料与公告',`<div class="profile-avatar-editor">${chatAvatar(c)}<button class="button secondary small-button" data-action="group-avatar" data-group="${esc(id)}">更换群头像</button></div><form><label>群名称<input name="name" aria-label="群名称" value="${esc(chatTitle(c))}" maxlength="40" required></label><label>群公告<textarea name="announcement" aria-label="群公告" maxlength="1000" rows="5" placeholder="让大家了解群内的新消息">${esc(info.announcement||c.announcement||'')}</textarea></label>${dialogActions('保存')}</form>`);formHandler(async data=>{await post('/api/groups/'+id,{name:data.get('name'),announcement:data.get('announcement')});await refreshConversations();featureDialog.close();refreshChatUI();notify('群资料已更新');});}
function confirmDialog(title,text,callback){const stamp=openDialog(title,`<p>${esc(text)}</p><form>${dialogActions('确认')}</form>`);formHandler(async()=>{await callback();if(featureDialog.open&&stamp===dialogEpoch)featureDialog.close();});}

const photoInput=document.createElement('input');photoInput.type='file';photoInput.accept='image/jpeg,image/png,image/webp';photoInput.id='photo-file';photoInput.hidden=true;document.body.append(photoInput);let photoTarget=null;
function pickPhoto(purpose,conversationId=null,groupId=null,camera=false){photoInput.removeAttribute('capture');if(camera)photoInput.setAttribute('capture','environment');if(purpose==='message'&&!conversationId){notify('请先打开一个会话');return;}if(state.uploading){notify('上一张照片正在上传，请稍候');return;}photoTarget={purpose,conversationId,groupId,ticket:sessionTicket(),dialogEpoch,replyToId:state.replyTo?.id};photoInput.value='';photoInput.click();}
async function compressPhoto(file){
  if(file.size>20*1024*1024)throw Error('照片太大，请选择 20 MB 以内的图片');
  const url=URL.createObjectURL(file);try{const image=await new Promise((accept,reject)=>{const img=new Image();img.onload=()=>accept(img);img.onerror=()=>reject(Error('无法读取照片，请选择 JPEG、PNG 或 WebP 图片'));img.src=url;});const scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight));if(!scale||!image.naturalWidth)throw Error('图片内容无法读取');const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.84));if(!blob||blob.size>3*1024*1024)throw Error('照片压缩后仍然太大，请选择较小的图片');return blob;}finally{URL.revokeObjectURL(url);}
}
photoInput.addEventListener('change',async()=>{
  const file=photoInput.files?.[0],target=photoTarget;if(!file||!target||!sameSession(target.ticket))return;state.uploading=true;notify('正在处理并上传照片…');
  const updateAvatar=html=>{if(featureDialog.open&&target.dialogEpoch===dialogEpoch){const current=featureDialog.querySelector('.profile-avatar-editor .avatar');if(current){current.outerHTML=html;hydrateMedia(featureDialog);}}};
  try{const blob=await compressPhoto(file);assertSession(target.ticket);const {media}=await api('/api/media?purpose='+encodeURIComponent(target.purpose==='message'?'message':'avatar'),{method:'POST',headers:{'Content-Type':'image/jpeg'},body:blob});assertSession(target.ticket);
    if(target.purpose==='message'){state.pendingPhoto={conversationId:target.conversationId,mediaId:media.id,clientId:uid(),ticket:target.ticket,replyToId:target.replyToId};await sendPendingPhoto();}
    else if(target.purpose==='group'){await post('/api/groups/'+target.groupId,{avatarId:media.id});assertSession(target.ticket);await refreshConversations();assertSession(target.ticket);const c=state.conversations.find(c=>c.id===target.groupId);if(c)updateAvatar(chatAvatar(c));if(state.activeId===target.groupId)refreshChatUI();notify('群头像已更新');}
    else{const {user}=await post('/api/me',{avatarId:media.id});assertSession(target.ticket);saveSession({token:target.ticket.token,user});renderSidebar();updateAvatar(avatar(user,'big'));notify('头像已更新');}
  }catch(error){if(sameSession(target.ticket)){notify(error.message);const retry=document.querySelector('.photo-retry');if(retry)retry.hidden=state.pendingPhoto?.conversationId!==state.activeId;}}finally{if(sameSession(target.ticket))state.uploading=false;}
});
async function sendPendingPhoto(){const p=state.pendingPhoto;if(!p)return;assertSession(p.ticket);try{const {message}=await post('/api/conversations/'+p.conversationId+'/messages',{kind:'image',mediaId:p.mediaId,clientId:p.clientId,...(p.replyToId?{replyToId:p.replyToId}:{})});assertSession(p.ticket);state.pendingPhoto=null;if(state.replyTo?.id===p.replyToId){state.replyTo=null;renderReplyComposer();saveComposerDraft();}if(state.activeId===p.conversationId){mergeMessages([message]);renderMessages();const retry=document.querySelector('.photo-retry');if(retry)retry.hidden=true;await markRead(p.conversationId);}await refreshConversations();notify('照片已发送');}catch(error){if(sameSession(p.ticket)){const retry=document.querySelector('.photo-retry');if(retry)retry.hidden=p.conversationId!==state.activeId;}throw error;}}
async function viewPhoto(id){try{const url=await mediaUrl(id);if(!url)return;imageDialog.querySelector('img').src=url;if(!imageDialog.open)imageDialog.showModal();}catch(error){notify(error.message);}}

function updateConnection(){for(const label of document.querySelectorAll('.connection-status')){label.classList.toggle('connected',state.connected);label.classList.toggle('connecting',!state.connected);label.textContent=state.connected?'已连接':'重连中';}const c=active(),status=document.querySelector('.partner-state');if(c&&status)status.textContent=isGroup(c)?`${c.memberCount||''} 位成员`:(state.online.has(c.partner?.id)?'在线，聊一聊吧':'消息会在对方上线后送达');}
async function syncSession(){const ticket=sessionTicket();await Promise.all([refreshConversations(),relationships()]);assertSession(ticket);if(state.activeId&&!state.historyJump){const id=state.activeId;const result=await api('/api/conversations/'+id+'/messages');if(id===state.activeId&&!state.page){state.messages=result.messages;state.hasMore=result.hasMore;renderMessages(false);}}}
function connectSocket(attempt=0){
  if(!state.token)return;const token=state.token,ticket=sessionTicket(),url=new URL(apiBase);url.protocol=url.protocol==='https:'?'wss:':'ws:';url.pathname='/ws';url.search='';const socket=new WebSocket(url,['ichat.v1',token]);state.socket=socket;
  socket.addEventListener('open',()=>{if(state.socket!==socket||!sameSession(ticket))return;state.connected=true;updateConnection();syncSession().catch(()=>{});api('/api/calls/current').then(({call})=>{if(state.socket===socket&&sameSession(ticket)&&call)calls.restore(call);}).catch(()=>{});});
  socket.addEventListener('message',event=>{if(state.socket!==socket||!sameSession(ticket))return;try{const data=JSON.parse(event.data);
    if(data.type?.startsWith('call-')){if(data.type==='call-state'&&data.call?.state!=='ended'&&voiceSession?.recording)stopVoiceRecording();calls.handleEvent(data);}
    else if(data.type==='presence'){state.online=new Set(data.userIds);updateConnection();}
    else if(data.type==='message'){const index=state.conversations.findIndex(c=>c.id===data.conversation.id);if(index>=0)state.conversations.splice(index,1);state.conversations.unshift(data.conversation);if(state.activeId===data.message.conversationId&&!state.page){const container=document.querySelector('#messages'),nearBottom=!container||container.scrollHeight-container.scrollTop-container.clientHeight<140;mergeMessages([data.message]);renderMessages(!state.historyJump&&(nearBottom||data.message.senderId===state.user.id));if(document.visibilityState==='visible')markRead(state.activeId);}if(state.tab==='chats')renderList();showMessageReminder(data);showBrowserNotification(data);updateConnection();}
    else if(data.type==='message-updated'){if(state.messages.some(m=>m.id===data.message.id)){mergeMessages([data.message]);renderMessages(false);}if(state.replyTo?.id===data.message.id){state.replyTo=null;renderReplyComposer();saveComposerDraft();}clearMedia();hydrateMedia();refreshConversations().catch(()=>{});}
    else if(data.type==='message-hidden'){state.messages=state.messages.filter(m=>m.id!==data.messageId);renderMessages(false);refreshConversations().catch(()=>{});}
    else if(data.type==='read'){const c=state.conversations.find(row=>row.id===data.conversationId);if(c){c.unread=0;c.markedUnread=false;}if(state.tab==='chats')renderList();}
    else if(data.type==='relationship'){relationships().catch(()=>{});refreshConversations().catch(()=>{});}
    else if(data.type==='conversation'){refreshConversations().then(()=>{assertSession(ticket);refreshChatUI();}).catch(()=>{});}
    else if(data.type==='conversation-removed'){state.conversations=state.conversations.filter(c=>c.id!==data.conversationId);state.drafts.delete(data.conversationId);if(state.pendingRich?.conversationId===data.conversationId)state.pendingRich=null;if(state.pendingPhoto?.conversationId===data.conversationId)state.pendingPhoto=null;if(state.activeId===data.conversationId){state.activeId=null;state.messages=[];state.replyTo=null;document.querySelector('.app-shell')?.classList.remove('chat-open');renderEmpty();if(!dialogIsDirty()&&!dialogSubmitting&&!momentUpload&&!voiceSession?.sending)featureDialog.close();imageDialog.close();clearMedia();notify('这个群聊已无法访问');}renderList();}
    else if(data.type==='moments'){if(state.page==='moments'){state.momentsDirty=true;renderMoments();}}
    else if(data.type==='profile'){for(const c of state.conversations)if(c.partner?.id===data.user.id){c.partner=data.user;if(!isGroup(c))c.title=data.user.displayName;}state.contacts=state.contacts.map(u=>u.id===data.user.id?{...u,...data.user}:u);state.messages=state.messages.map(m=>m.senderId===data.user.id?{...m,sender:data.user}:m);if(data.user.id===state.user.id){api('/api/me').then(({user})=>{assertSession(ticket);state.user=user;saveSession({token:state.token,user});renderList();}).catch(()=>{});}else{renderList();refreshChatUI();}}
  }catch{}});
  socket.addEventListener('close',()=>{if(state.socket!==socket)return;state.connected=false;calls.connectionClosed();updateConnection();setTimeout(()=>{if(state.token===token&&state.socket===socket)connectSocket(Math.min(attempt+1,5));},Math.min(1000*2**attempt,15000));});socket.addEventListener('error',()=>{});
}
async function startSession(){const ticket=sessionTicket();state.tab='chats';state.query='';state.page=null;renderShell();await Promise.all([refreshConversations(),relationships()]);assertSession(ticket);connectSocket();state.notificationsEnabled=localStorage.getItem('ichat.notifications.'+state.user.id)==='1';if(nativeTools.isNative)syncNotificationState().catch(()=>{});if(demoIdentity&&state.conversations.length)await openConversation(state.conversations[0].id);if(query.get('add'))addFriendDialog(query.get('add'));if(state.pendingOpenId){const id=state.pendingOpenId;state.pendingOpenId=null;if(state.conversations.some(c=>c.id===id))await openConversation(id);}}
function showConnection(){if(fixedServer)return;document.querySelector('#server-url').value=apiBase;document.querySelector('#connection-error').textContent='';document.querySelector('#connection-dialog').showModal();}
