const calls=createCallController({getSession:()=>({token:state.token,user:state.user,apiBase}),getSocket:()=>state.socket,notify});
let dialogSubmitting=false,voiceSession=null,fileTarget=null,momentUpload=false,pageEpoch=0,momentRequest=0;
const nativeFeatureClose=featureDialog.close.bind(featureDialog);
featureDialog.close=function(value){if(featureDialog.open){dialogEpoch++;dialogSubmitting=false;disposeVoice();featureDialog.dataset.section='';}nativeFeatureClose(value);};
const sameDialog=stamp=>featureDialog.open&&stamp===dialogEpoch;
const searchMessages=new Map();
function displayContact(user){if(!user)return '';return state.contacts.find(u=>u.id===user.id)?.remark||user.remark||user.displayName||user.username||'朋友';}
function deviceLabel(){if(nativeTools.isNative)return 'Android 手机';if(window.Capacitor?.getPlatform?.()==='ios')return 'iPhone / iPad';const ua=navigator.userAgent||'';return /iPhone|iPad/i.test(ua)?'iPhone / iPad 浏览器':/Android/i.test(ua)?'安卓浏览器':/Windows/i.test(ua)?'Windows 浏览器':/Macintosh|Mac OS/i.test(ua)?'Mac 浏览器':'网页设备';}
function saveComposerDraft(){const input=document.querySelector('#message-input');if(state.activeId&&input)state.drafts.set(state.activeId,{body:input.value,replyTo:state.replyTo});}
function messageSummary(m){return m?.kind==='voice'?'[语音]':m?.kind==='file'?'[文件] '+(m.media?.filename||m.body||''):m?.kind==='image'?'[照片]':m?.kind==='location'?'[位置] '+(m.location?.label||'当前位置'):m?.kind==='contact'?'[名片] '+(m.contact?.displayName||'朋友'):m?.kind==='withdrawn'?'这条消息已撤回':String(m?.body||'').slice(0,180);}
function renderReplyComposer(){const bar=document.querySelector('#reply-composer');if(!bar)return;bar.innerHTML=state.replyTo?`<div class="reply-draft"><span>回复 ${esc(state.replyTo.sender?.displayName||'消息')}<small>${esc(messageSummary(state.replyTo))}</small></span><button type="button" class="icon-button" data-action="cancel-reply" aria-label="取消回复">${icon('close')}</button></div>`:'';}
function bytesLabel(size){return size>=1048576?(size/1048576).toFixed(1)+' MB':Math.max(1,Math.ceil(size/1024))+' KB';}
function messageBody(m){
  const mediaId=m.media?.id||m.mediaId;
  if(m.kind==='image'&&mediaId)return `<button class="photo-bubble" data-action="view-photo" data-id="${esc(mediaId)}" aria-label="查看聊天照片"><span>正在加载照片…</span><img data-media="${esc(mediaId)}" alt="聊天照片" hidden></button>`;
  if(m.kind==='voice'&&mediaId)return `<div class="voice-bubble">${icon('mic')}<span>${Math.max(1,Math.round((m.durationMs||1000)/1000))} 秒</span><audio controls preload="none" data-media="${esc(mediaId)}" aria-label="播放语音消息"></audio></div>`;
  if(m.kind==='file'&&mediaId)return `<button class="file-bubble" data-action="download-file" data-id="${esc(mediaId)}" data-name="${esc(m.media?.filename||m.body||'文件')}">${icon('file')}<span><b>${esc(m.media?.filename||m.body||'文件')}</b><small>${bytesLabel(m.media?.size||0)} · 点击保存</small></span>${icon('download')}</button>`;
  if(m.kind==='location'&&m.location)return `<button class="location-bubble" data-action="view-location" data-lat="${esc(m.location.latitude)}" data-lon="${esc(m.location.longitude)}" data-label="${esc(m.location.label||'当前位置')}"><span class="map-tile">${icon('location')}</span><b>${esc(m.location.label||'当前位置')}</b><small>点按查看位置</small></button>`;
  if(m.kind==='contact'&&m.contact)return `<button class="contact-bubble" data-action="contact-details" data-id="${esc(m.contact.id)}">${avatar(m.contact)}<span><b>${esc(m.contact.displayName)}</b><small>@${esc(m.contact.username)}</small><em>小紫在 名片</em></span></button>`;
  if(m.kind==='call')return `<p class="call-summary">${icon('phone')}${esc(m.body||'通话记录')}</p>`;
  return `<p>${esc(m.body)}</p>`;
}
function formSnapshot(form){return JSON.stringify([...new FormData(form)].map(([k,v])=>[k,typeof v==='string'?v:[v.name,v.size]]));}
function dialogIsDirty(){const form=featureDialog.querySelector('form');return !!(voiceSession?.recording||voiceSession?.blob||(form&&!form.dataset.transient&&form.dataset.initial!==undefined&&formSnapshot(form)!==form.dataset.initial));}
function closeFeature(force=false){if(!featureDialog.open)return true;if(!force&&(dialogSubmitting||voiceSession?.sending)){notify('正在保存，请稍候');return false;}if(!force&&momentUpload){notify('照片正在上传，请稍候');return false;}if(!force&&dialogIsDirty()&&!window.confirm('内容尚未保存，确认放弃这次编辑？'))return false;featureDialog.close();return true;}
featureDialog.addEventListener('cancel',event=>{event.preventDefault();closeFeature();});
featureDialog.addEventListener('close',()=>{if(!featureDialog.open){disposeVoice();dialogSubmitting=false;}});
function returnManagement(){dialogEpoch++;pageEpoch++;state.activeId=null;state.page=null;state.messages=[];state.replyTo=null;const shell=document.querySelector('.app-shell');shell?.classList.remove('chat-open','management-feature');state.tab='manage';renderSidebar();renderEmpty();}
function backToList(){if(state.tab==='manage'&&['moments','favorites'].includes(state.page)){returnManagement();return;}dialogEpoch++;pageEpoch++;saveComposerDraft();state.activeId=null;state.page=null;state.messages=[];state.replyTo=null;document.querySelector('.app-shell')?.classList.remove('chat-open');renderEmpty();renderList();}
function handleBack(){if(imageDialog.open){imageDialog.close();return true;}if(featureDialog.open){closeFeature();return true;}if(state.activeId||state.page){backToList();return true;}return false;}
window.addEventListener('ichat-back',event=>{if(event.defaultPrevented)return;if(handleBack())event.preventDefault();});
try{history.pushState({ichatUI:true},'',location.href);window.addEventListener('popstate',()=>{if(handleBack())history.pushState({ichatUI:true},'',location.href);});}catch{}
window.addEventListener('ichat-open-conversation',async event=>{const id=event.detail?.conversationId;if(!id)return;if(!state.token){state.pendingOpenId=id;return;}if(voiceSession?.recording){notify('请先完成当前录音');return;}const ticket=sessionTicket();try{await refreshConversations();assertSession(ticket);if(!state.conversations.some(c=>c.id===id)){notify('这段对话当前无法访问');return;}if(!closeFeature())return;await openConversation(id);}catch(error){if(sameSession(ticket))notify(error.message);}});

function chatMenu(){const c=active();if(!c)return;openDialog('聊天',`<div class="action-menu"><button data-action="${isGroup(c)?'group-info':'contact-info'}">${icon(isGroup(c)?'users':'user')}${isGroup(c)?'群聊资料':'好友资料'}<span>${esc(chatTitle(c))}</span></button><button data-action="chat-search" data-id="${esc(c.id)}">${icon('search')}搜索聊天记录<span>查找这段对话中的内容</span></button><button data-action="chat-settings" data-id="${esc(c.id)}">${icon('settings')}会话设置<span>置顶、免打扰与清空记录</span></button></div>`);}
async function chatSettings(id){const c=state.conversations.find(c=>c.id===id);if(!c)return;openDialog('会话设置',`<p class="setting-title">${esc(chatTitle(c))}</p><form><label class="toggle-row"><span>置顶聊天</span><input type="checkbox" name="pinned" ${c.pinned?'checked':''}></label><label class="toggle-row"><span>消息免打扰</span><input type="checkbox" name="muted" ${c.muted?'checked':''}></label><label class="toggle-row"><span>标记为未读</span><input type="checkbox" name="markedUnread" ${c.markedUnread?'checked':''}></label>${dialogActions('保存设置')}</form><button class="text-button danger-text full-width" data-action="clear-history" data-id="${esc(id)}">清空我的聊天记录</button>`);formHandler(async data=>{const markedUnread=data.has('markedUnread');await post('/api/conversations/'+id+'/settings',{pinned:data.has('pinned'),muted:data.has('muted'),markedUnread});await refreshConversations();featureDialog.close();if(markedUnread&&state.activeId===id)backToList();notify('会话设置已保存');});}
function sourceMessage(id){return state.messages.find(m=>m.id===id)||searchMessages.get(id);}
function messageActions(id){const m=sourceMessage(id);if(!m)return;const canRecall=m.senderId===state.user.id&&Date.now()-Date.parse(m.createdAt)<120000&&m.kind!=='call',normal=!['system','withdrawn'].includes(m.kind)&&!m.withdrawn;openDialog('消息操作',`<div class="message-action-preview">${esc(messageSummary(m))}</div><div class="message-action-grid">${normal?`<button data-action="reply-message" data-id="${esc(id)}">${icon('reply')}回复</button>${m.kind!=='call'?`<button data-action="forward-message" data-id="${esc(id)}">${icon('forward')}转发</button>`:''}<button data-action="favorite-message" data-id="${esc(id)}">${icon('star')}收藏</button>`:''}${canRecall&&normal?`<button data-action="recall-message" data-id="${esc(id)}">${icon('back')}撤回</button>`:''}<button data-action="hide-message" data-id="${esc(id)}">${icon('close')}从我的记录隐藏</button></div>`);}
function forwardDialog(id){const m=sourceMessage(id);if(!m)return;const clientId=uid();openDialog('转发给',`<form><p class="hint">${esc(messageSummary(m))}</p><p class="hint">最多选择 9 个会话。</p><div class="friend-choices">${state.conversations.map(c=>`<label class="friend-choice"><input type="checkbox" name="conversationIds" value="${esc(c.id)}">${chatAvatar(c)}<span><b>${esc(chatTitle(c))}</b><small>${isGroup(c)?'群聊':'好友'}</small></span></label>`).join('')||'<p class="hint">先和好友开始一段对话吧。</p>'}</div>${dialogActions('转发')}</form>`,true);formHandler(async data=>{const conversationIds=data.getAll('conversationIds');if(!conversationIds.length||conversationIds.length>9)throw Error('请选择 1 到 9 个会话');await post('/api/messages/'+id+'/forward',{conversationIds,clientId});await refreshConversations();featureDialog.close();notify('已转发');});}
function chatSearch(id){openDialog('搜索聊天记录',`<form data-transient="true"><label>查找内容<input name="q" aria-label="搜索聊天记录" type="search" maxlength="100" required placeholder="输入文字或文件名"></label><p class="form-error" role="alert"></p><button class="button full-width" type="submit">搜索</button></form><div id="chat-search-results"></div>`,true);formHandler(async data=>{const stamp=dialogEpoch,{messages}=await api('/api/conversations/'+id+'/search?q='+encodeURIComponent(String(data.get('q')).trim()));if(stamp!==dialogEpoch)return;const box=featureDialog.querySelector('#chat-search-results');if(!box)return;searchMessages.clear();for(const m of messages)searchMessages.set(m.id,m);box.innerHTML=messages.map(m=>`<button class="search-result" data-action="search-result" data-id="${esc(m.id)}" data-conversation="${esc(id)}"><b>${esc(m.sender?.displayName||'朋友')}<small>${time(m.createdAt)}</small></b><span>${esc(messageSummary(m))}</span></button>`).join('')||'<p class="hint">没有找到匹配的记录。</p>';});}
async function jumpToMessage(id,conversationId=state.activeId){const m=sourceMessage(id);if(!m){notify('这条引用暂时无法定位，可以搜索聊天记录');return;}closeFeature(true);if(state.activeId!==conversationId)await openConversation(conversationId);let element=document.querySelector(`[data-message-id="${CSS.escape(id)}"]`);if(!element){const ticket=sessionTicket(),result=await api('/api/conversations/'+conversationId+'/messages?before='+(m.seq+1));assertSession(ticket);if(state.activeId!==conversationId)return;state.messages=result.messages;state.hasMore=result.hasMore;state.historyJump=true;renderMessages(false);element=document.querySelector(`[data-message-id="${CSS.escape(id)}"]`);}if(element){element.scrollIntoView({block:'center',behavior:'smooth'});element.classList.add('message-highlight');setTimeout(()=>element.classList.remove('message-highlight'),2200);}else notify('这条消息已不在可见记录中');}
async function latestMessages(){const ticket=sessionTicket(),id=state.activeId;if(!id)return;const result=await api('/api/conversations/'+id+'/messages');assertSession(ticket);if(state.activeId!==id)return;state.messages=result.messages;state.hasMore=result.hasMore;state.historyJump=false;renderMessages();await markRead(id);}

async function contactDetails(id){const ticket=sessionTicket(),stamp=dialogEpoch,data=await api('/api/contacts/'+id);assertSession(ticket);if(stamp!==dialogEpoch)return;const u=data.user,friend=data.isFriend||data.relationship==='friend',self=u.id===state.user.id,blocked=data.blocked??u.blocked,starred=data.starred??u.starred;openDialog(self?'我的名片':'朋友资料',`<div class="contact-profile">${avatar(u,'big')}<h3>${esc(data.remark||u.remark||u.displayName)}</h3>${data.remark||u.remark?`<p>昵称：${esc(u.displayName)}</p>`:''}<p>@${esc(u.username)}</p><p>${esc(u.about||'还没有填写个人简介')}</p>${blocked?'<p class="danger-text">已加入黑名单</p>':''}</div>${friend?`<div class="contact-settings"><button class="button full-width" data-action="open-contact" data-id="${esc(id)}" ${blocked?'disabled':''}>发消息</button><button class="button secondary full-width" data-action="edit-remark" data-id="${esc(id)}">修改备注</button><button class="text-button" data-action="contact-setting" data-id="${esc(id)}" data-key="starred" data-value="${starred?'false':'true'}">${starred?'取消星标':'设为星标好友'}</button><button class="text-button" data-action="contact-setting" data-id="${esc(id)}" data-key="blocked" data-value="${blocked?'false':'true'}">${blocked?'移出黑名单':'加入黑名单'}</button><button class="text-button danger-text" data-action="remove-friend" data-id="${esc(id)}" data-name="${esc(u.displayName)}">删除好友</button></div>`:self?'<p class="hint">朋友可以通过你的账号或二维码找到你。</p>':`<button class="button full-width" data-action="request-by-account" data-username="${esc(u.username)}">添加到联系人</button>`}`);}
async function remarkDialog(id){const stamp=dialogEpoch,{user,remark}=await api('/api/contacts/'+id);if(stamp!==dialogEpoch)return;openDialog('修改好友备注',`<form><label>备注名<input name="remark" aria-label="备注名" value="${esc(remark||user.remark||'')}" maxlength="24" placeholder="仅自己可见"></label>${dialogActions('保存')}</form>`);formHandler(async data=>{await post('/api/contacts/'+id+'/settings',{remark:data.get('remark')});await relationships();featureDialog.close();renderList();refreshChatUI();notify('备注已保存');});}
async function contactSetting(id,key,value){const stamp=dialogEpoch;if(!['starred','blocked'].includes(key))return;await post('/api/contacts/'+id+'/settings',{[key]:value});await Promise.all([relationships(),refreshConversations()]);if(sameDialog(stamp))await contactDetails(id);notify(key==='blocked'?(value?'已加入黑名单':'已移出黑名单'):(value?'已设为星标好友':'已取消星标'));}
async function blockedList(){const stamp=dialogEpoch,{users}=await api('/api/blocked');if(stamp!==dialogEpoch)return;openDialog('黑名单',`<p class="hint">加入黑名单后，双方无法发起新的私聊和通话。</p>${users.map(u=>`<div class="blocked-row">${avatar(u)}<span><b>${esc(u.displayName)}</b><small>@${esc(u.username)}</small></span><button class="text-button" data-action="unblock-contact" data-id="${esc(u.id)}">移出</button></div>`).join('')||'<p class="hint">黑名单为空。</p>'}`);}
async function groupAliasDialog(id){const stamp=dialogEpoch,{myAlias,conversation}=await api('/api/groups/'+id);if(stamp!==dialogEpoch)return;openDialog('我的群内昵称',`<form><label>群内昵称<input name="alias" aria-label="群内昵称" maxlength="24" value="${esc(myAlias||conversation.myAlias||'')}" placeholder="留空时使用个人昵称"></label>${dialogActions('保存')}</form>`);formHandler(async data=>{await post('/api/groups/'+id+'/alias',{alias:data.get('alias')});await refreshConversations();featureDialog.close();await syncSession();notify('群内昵称已保存');});}

function attachmentMenu(){if(!active())return;openDialog('分享给朋友',`<div class="attachment-grid"><button data-action="send-camera">${icon('camera')}拍照</button><button data-action="send-photo">${icon('photo')}照片</button><button data-action="record-voice">${icon('mic')}语音消息</button><button data-action="send-file">${icon('file')}文件</button><button data-action="send-location">${icon('location')}当前位置</button><button data-action="send-contact">${icon('user')}好友名片</button></div>`);}
async function sendRich(kind,fields,options={}){const ticket=options.ticket||sessionTicket(),id=options.conversationId||state.activeId;if(!id)throw Error('请先打开一个会话');assertSession(ticket);if(!state.conversations.some(c=>c.id===id))throw Error('这段对话当前无法发送消息');const clientId=options.clientId||uid();if(state.pendingRich&&state.pendingRich.clientId!==clientId)throw Error('请先重试或取消上一份未发送的附件');const pending={kind,...fields,conversationId:id,clientId,ticket,replyToId:Object.hasOwn(options,'replyToId')?options.replyToId:state.replyTo?.id};state.pendingRich=pending;await sendPendingRich();}
async function sendPendingRich(){const p=state.pendingRich;if(!p)return;assertSession(p.ticket);const {conversationId,ticket,...payload}=p;try{const {message}=await post('/api/conversations/'+conversationId+'/messages',payload);assertSession(ticket);if(state.pendingRich?.clientId===p.clientId)state.pendingRich=null;if(state.activeId===conversationId){mergeMessages([message]);renderMessages();if(state.replyTo?.id===p.replyToId){state.replyTo=null;renderReplyComposer();saveComposerDraft();}const retry=document.querySelector('.attachment-retry');if(retry)retry.hidden=true;await markRead(conversationId);}await refreshConversations();}catch(error){if(sameSession(ticket)){const retry=document.querySelector('.attachment-retry');if(retry)retry.hidden=state.activeId!==conversationId;}throw error;}}
const fileInput=document.createElement('input');fileInput.type='file';fileInput.hidden=true;fileInput.id='attachment-file';document.body.append(fileInput);
function pickFile(){if(!state.activeId)return;if(state.uploading||state.pendingRich){notify('请先处理上一份附件');return;}fileTarget={ticket:sessionTicket(),conversationId:state.activeId,replyToId:state.replyTo?.id};fileInput.value='';fileInput.click();}
fileInput.addEventListener('change',async()=>{const file=fileInput.files?.[0],target=fileTarget;if(!file||!target||!sameSession(target.ticket))return;if(file.size===0||file.size>10*1024*1024){notify('请选择 10 MB 以内的非空文件');return;}state.uploading=true;try{notify('正在上传文件…');const {media}=await api('/api/media?purpose=file',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)},body:file});assertSession(target.ticket);await sendRich('file',{mediaId:media.id},target);notify('文件已发送');}catch(error){if(sameSession(target.ticket))notify(error.message);}finally{if(sameSession(target.ticket))state.uploading=false;}});
async function downloadFile(id,filename){const ticket=sessionTicket();if(nativeTools.isNative){await nativeTools.downloadMedia({base:apiBase,token:ticket.token,id,filename});assertSession(ticket);notify('文件已保存，请在下载中查看');return;}const url=await mediaUrl(id);assertSession(ticket);if(!url)return;const link=document.createElement('a');link.href=url;link.download=String(filename||'小紫在文件').replace(/[\\/\x00-\x1f]/g,'_');document.body.append(link);link.click();link.remove();notify('已开始保存文件');}
async function sendLocation(){const target={ticket:sessionTicket(),conversationId:state.activeId,replyToId:state.replyTo?.id},stamp=dialogEpoch;if(!target.conversationId)return;notify('正在获取当前位置…');const result=nativeTools.isNative?await nativeTools.getLocation():await new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('当前设备不支持定位'));navigator.geolocation.getCurrentPosition(p=>resolve(p.coords),()=>reject(Error('未能获取位置，请在权限中允许定位后重试')),{enableHighAccuracy:true,timeout:15000,maximumAge:30000});});assertSession(target.ticket);if(stamp!==dialogEpoch)return;const latitude=Number(result.latitude??result.coords?.latitude),longitude=Number(result.longitude??result.coords?.longitude);if(!Number.isFinite(latitude)||!Number.isFinite(longitude))throw Error('暂时无法读取位置');openDialog('发送位置',`<div class="location-preview map-tile">${icon('location')}</div><p class="hint">${latitude.toFixed(5)}, ${longitude.toFixed(5)}</p><form><label>位置名称<input name="label" aria-label="位置名称" value="当前位置" maxlength="120" required></label>${dialogActions('发送位置')}</form>`);formHandler(async data=>{await sendRich('location',{latitude,longitude,label:data.get('label')},target);featureDialog.close();notify('位置已发送');});}
function viewLocation(latitude,longitude,label){const lat=Number(latitude),lon=Number(longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return;openDialog('位置',`<div class="location-preview map-tile">${icon('location')}</div><h3>${esc(label||'当前位置')}</h3><p class="hint">${lat.toFixed(5)}, ${lon.toFixed(5)}</p><a class="button map-link" href="https://www.openstreetmap.org/?mlat=${lat}&mlon=${lon}#map=16/${lat}/${lon}" target="_blank" rel="noopener noreferrer">打开地图</a>`);}
function contactCardDialog(){const target={ticket:sessionTicket(),conversationId:state.activeId,replyToId:state.replyTo?.id};if(!target.conversationId)return;const users=[state.user,...state.contacts.filter(u=>!u.blocked)];openDialog('发送好友名片',`<form><div class="friend-choices">${users.map(u=>`<label class="friend-choice"><input type="radio" name="contactId" value="${esc(u.id)}" required>${avatar(u)}<span><b>${esc(displayContact(u))}${u.id===state.user.id?'（我）':''}</b><small>@${esc(u.username)}</small></span></label>`).join('')}</div>${dialogActions('发送名片')}</form>`,true);formHandler(async data=>{await sendRich('contact',{contactId:data.get('contactId')},target);featureDialog.close();notify('名片已发送');});}
function recordVoiceDialog(target={ticket:sessionTicket(),conversationId:state.activeId,replyToId:state.replyTo?.id}){
  if(!target.conversationId)return;if(calls.isActive?.()){notify('请先结束当前通话');return;}if(state.pendingRich){notify('请先处理上一份未发送的附件');return;}if(!window.isSecureContext){notify('请在安全连接或手机应用中使用语音');return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('当前设备暂不支持录音，请使用手机应用或更新浏览器');return;}
  const stamp=openDialog('语音消息','<div class="voice-panel"></div>');voiceSession={...target,stamp,clientId:uid(),recording:false,starting:false,sending:false,blob:null,url:null,durationMs:0,chunks:[],stream:null,recorder:null,timer:null};renderVoicePanel();
}
function renderVoicePanel(){const v=voiceSession,box=featureDialog.querySelector('.voice-panel');if(!v||!box||v.stamp!==dialogEpoch)return;box.innerHTML=`<div class="record-orb ${v.recording?'recording':''}">${icon('mic')}</div><p class="record-time">${v.recording?Math.floor((performance.now()-v.startedAt)/1000):Math.round(v.durationMs/1000)} 秒</p><p class="hint">${v.recording?'录音中，最长 60 秒':v.blob?'听听这段语音，再发送给朋友。':'准备好后点按开始录音，最长 60 秒。'}</p>${v.blob?`<audio class="voice-preview" controls src="${esc(v.url)}"></audio><div class="dialog-actions"><button class="button secondary" data-action="voice-redo" ${v.sending?'disabled':''}>重新录制</button><button class="button" data-action="voice-send" ${v.sending?'disabled':''}>${v.sending?'正在发送…':'发送语音'}</button></div>`:`<button class="button full-width" data-action="${v.recording?'voice-stop':'voice-start'}" ${v.starting?'disabled':''}>${v.recording?'结束录音':v.starting?'正在打开麦克风…':'开始录音'}</button>`}`;}
async function beginVoiceRecording(){const v=voiceSession;if(!v||v.starting||v.recording)return;v.starting=true;renderVoicePanel();try{if(nativeTools.isNative){const permission=await nativeTools.requestPermission('microphone');const micPermission=permissionValue(permission?.microphone);if(micPermission==='unsupported')throw Error('这台设备没有可用的麦克风');if(micPermission!=='granted')throw Error('麦克风未获允许，可以在权限中心重新设置');}assertSession(v.ticket);if(calls.isActive?.())throw Error('请先结束当前通话');if(voiceSession!==v||v.stamp!==dialogEpoch)return;const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});if(voiceSession!==v||!sameSession(v.ticket)||v.stamp!==dialogEpoch||calls.isActive?.()){stream.getTracks().forEach(t=>t.stop());return;}v.stream=stream;const mime=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(type=>MediaRecorder.isTypeSupported(type));const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});v.recorder=recorder;v.chunks=[];recorder.addEventListener('dataavailable',e=>{if(e.data.size)v.chunks.push(e.data);});recorder.addEventListener('error',()=>{if(voiceSession===v){disposeVoice();notify('录音暂时失败，请重试');closeFeature(true);}});recorder.addEventListener('stop',()=>{stream.getTracks().forEach(t=>t.stop());clearInterval(v.timer);if(voiceSession!==v||!sameSession(v.ticket)||v.stamp!==dialogEpoch)return;v.recording=false;v.durationMs=Math.min(60000,Math.round(performance.now()-v.startedAt));const type=(recorder.mimeType||v.chunks[0]?.type||'audio/webm').split(';')[0];const blob=new Blob(v.chunks,{type});if(v.durationMs<1000||!blob.size||blob.size>5*1024*1024){v.blob=null;v.durationMs=0;notify('请录制 1 到 60 秒的语音');}else{v.blob=blob;v.url=URL.createObjectURL(blob);}renderVoicePanel();});recorder.start(250);v.startedAt=performance.now();v.recording=true;v.timer=setInterval(()=>{if(voiceSession!==v)return;const elapsed=performance.now()-v.startedAt;const label=featureDialog.querySelector('.record-time');if(label)label.textContent=Math.floor(elapsed/1000)+' 秒';if(elapsed>=60000)stopVoiceRecording();},250);}catch(error){if(voiceSession===v){v.stream?.getTracks().forEach(t=>t.stop());const tips={NotAllowedError:'麦克风未获允许，仍可继续文字聊天',NotFoundError:'这台设备没有可用的麦克风',NotReadableError:'麦克风暂时无法使用，请检查是否被其他应用占用',NotSupportedError:'当前设备不支持录音，请更新浏览器或使用手机应用',SecurityError:'请在安全连接或手机应用中使用录音',AbortError:'录音启动已取消'};notify(tips[error.name]||error.message||'暂时无法打开麦克风');}}finally{if(voiceSession===v){v.starting=false;renderVoicePanel();}}}
function stopVoiceRecording(){const v=voiceSession;if(!v)return;clearInterval(v.timer);if(v.recorder?.state==='recording'){v.recording=false;v.recorder.stop();}}
function disposeVoice(){const v=voiceSession;if(!v)return;voiceSession=null;for(const audio of featureDialog.querySelectorAll('.voice-preview')){audio.pause();audio.removeAttribute('src');audio.load();}clearInterval(v.timer);if(v.recorder?.state==='recording')v.recorder.stop();v.stream?.getTracks().forEach(t=>t.stop());if(v.url)URL.revokeObjectURL(v.url);}
async function sendVoice(){const v=voiceSession;if(!v?.blob||v.sending)return;v.sending=true;renderVoicePanel();try{assertSession(v.ticket);if(!v.mediaId){const {media}=await api('/api/media?purpose=voice',{method:'POST',headers:{'Content-Type':v.blob.type},body:v.blob});assertSession(v.ticket);v.mediaId=media.id;}if(voiceSession!==v||v.stamp!==dialogEpoch)return;await sendRich('voice',{mediaId:v.mediaId,durationMs:v.durationMs},{ticket:v.ticket,conversationId:v.conversationId,replyToId:v.replyToId,clientId:v.clientId});closeFeature(true);notify('语音已发送');}catch(error){if(sameSession(v.ticket))notify(error.message);}finally{if(voiceSession===v){v.sending=false;renderVoicePanel();}}}

function featurePage(name,title,actions=''){const fromManagement=state.tab==='manage'&&['moments','favorites'].includes(name);if(fromManagement){disposeEnterprise();document.querySelector('.app-shell')?.classList.add('management-feature');}dialogEpoch++;pageEpoch++;saveComposerDraft();state.activeId=null;state.messages=[];state.replyTo=null;state.page=name;const pane=document.querySelector('#chat-pane');pane.className='chat-pane feature-page';pane.innerHTML=`<header class="chat-top"><button class="icon-button management-feature-back" data-action="back" aria-label="${fromManagement?'返回管理':'返回'}">${icon('back')}${fromManagement?'<span>返回管理</span>':''}</button><div class="chat-heading"><h2>${esc(title)}</h2></div><div class="top-right">${actions}</div></header><div class="feature-scroll" id="feature-scroll"><p class="hint">正在加载…</p></div>`;document.querySelector('.app-shell')?.classList.add('chat-open');renderList();}
async function favoritesPage(){closeFeature(true);featurePage('favorites','我的收藏');const ticket=sessionTicket(),page=pageEpoch,{favorites}=await api('/api/favorites');assertSession(ticket);if(state.page!=='favorites'||page!==pageEpoch)return;state.favorites=favorites;renderFavorites();}
function renderFavorites(){const box=document.querySelector('#feature-scroll');if(!box||state.page!=='favorites')return;box.innerHTML=`<div class="page-intro"><span class="eyebrow">好好收藏</span><h2>把喜欢的，好好收着。</h2><p>收藏仅自己可见。</p></div><div class="favorite-list">${state.favorites.map(f=>{const m=f.message||f.messageSnapshot||{};return `<article class="saved-card"><div class="saved-heading">${avatar(m.sender||state.user,'small')}<span><b>${esc(m.sender?.displayName||'收藏消息')}</b><small>${day(f.createdAt)} ${time(f.createdAt)}</small></span><button class="icon-button" data-action="remove-favorite" data-id="${esc(f.id)}" aria-label="移除收藏">${icon('close')}</button></div><div class="saved-content">${messageBody(m)}</div>${state.conversations.some(c=>c.id===m.conversationId)?`<button class="text-button" data-action="open-chat" data-id="${esc(m.conversationId)}">打开原会话</button>`:''}</article>`;}).join('')||'<div class="empty-list"><b>还没有收藏</b>点按聊天消息旁的更多按钮，将文字、照片或文件收藏起来。</div>'}</div>`;hydrateMedia(box);}
async function loadMoments(append=false){
  const ticket=sessionTicket();if(state.page!=='moments')featurePage('moments','朋友圈',`<button class="icon-button" data-action="compose-moment" aria-label="发布朋友圈">${icon('camera')}</button>`);
  const page=pageEpoch,request=++momentRequest,before=append?state.moments.at(-1)?.seq:null;
  const {posts,hasMore}=await api('/api/moments'+(before?'?before='+before:''));assertSession(ticket);
  if(state.page!=='moments'||page!==pageEpoch||request!==momentRequest)return;
  state.moments=append?[...state.moments,...posts.filter(post=>!state.moments.some(old=>old.id===post.id))]:posts;state.hasMoreMoments=hasMore;state.momentsDirty=false;renderMoments();
}
function renderMoments(){const box=document.querySelector('#feature-scroll');if(!box||state.page!=='moments')return;const scroll=box.scrollTop;box.innerHTML=`<div class="moments-cover"><span class="eyebrow">日常与朋友</span><h2>朋友的日常</h2><p>分享给彼此熟悉的人。</p>${avatar(state.user,'big')}</div>${state.momentsDirty?'<button class="moment-refresh" data-action="refresh-moments">有新的动态，点此刷新</button>':''}<div class="moment-feed">${state.moments.map(p=>`<article class="moment-post" data-post-id="${esc(p.id)}"><button class="moment-avatar" data-action="contact-details" data-id="${esc(p.user.id)}">${avatar(p.user)}</button><div class="moment-content"><b class="moment-author">${esc(displayContact(p.user))}</b>${p.body?`<p class="moment-body">${esc(p.body)}</p>`:''}${p.media?.length?`<div class="moment-photos count-${p.media.length}">${p.media.map(m=>`<button data-action="view-photo" data-id="${esc(m.id)}" aria-label="查看朋友圈照片"><img data-media="${esc(m.id)}" alt="朋友圈照片" hidden></button>`).join('')}</div>`:''}<div class="moment-meta"><small>${day(p.createdAt)} ${time(p.createdAt)}</small>${p.user.id===state.user.id?`<button class="text-button danger-text" data-action="delete-moment" data-id="${esc(p.id)}">删除</button>`:''}<button class="moment-like ${p.likedByMe?'liked':''}" data-action="like-moment" data-id="${esc(p.id)}" aria-label="${p.likedByMe?'取消点赞':'点赞'}">${icon('heart')}<span>${p.likeCount||''}</span></button><button class="icon-button" data-action="comment-moment" data-id="${esc(p.id)}" aria-label="评论">${icon('chat')}</button></div>${p.likes?.length||p.comments?.length?`<div class="moment-reactions">${p.likes?.length?`<p class="moment-likes">${icon('heart')}${esc(p.likes.map(u=>displayContact(u)).join('、'))}</p>`:''}${(p.comments||[]).map(c=>`<div class="moment-comment"><span><b>${esc(displayContact(c.user))}：</b>${esc(c.body)}</span>${c.user.id===state.user.id||p.user.id===state.user.id?`<button class="comment-delete" data-action="delete-comment" data-id="${esc(c.id)}" data-post="${esc(p.id)}" aria-label="删除评论">×</button>`:''}</div>`).join('')}</div>`:''}</div></article>`).join('')||'<div class="empty-list"><b>记录第一个日常</b>你的动态会分享给当前好友。</div>'}</div>${state.hasMoreMoments?'<button class="load-older" data-action="older-moments">查看更多动态</button>':''}`;hydrateMedia(box);box.scrollTop=scroll;}
function updateMoment(post){if(!post)return;const index=state.moments.findIndex(p=>p.id===post.id);if(index>=0)state.moments[index]=post;else state.moments.unshift(post);renderMoments();}
function momentComposer(){const stamp=openDialog('分享此刻',`<form id="moment-form"><label>这一刻，想说点什么？<textarea name="body" aria-label="朋友圈内容" maxlength="2000" rows="5" placeholder="分享你的日常…"></textarea></label><input type="hidden" name="mediaIds" value=""><div id="moment-draft-photos" class="moment-draft-photos"></div><button type="button" class="button secondary full-width" data-action="moment-add-photos">${icon('photo')} 添加照片</button><p class="hint">最多 9 张照片，仅自己和当前好友可见。</p>${dialogActions('发布')}</form>`,true);state.momentDraft={stamp,media:[]};formHandler(async data=>{if(momentUpload)throw Error('照片正在上传，请稍候');const body=String(data.get('body')||'').trim(),mediaIds=state.momentDraft?.media.map(m=>m.id)||[];if(!body&&!mediaIds.length)throw Error('写点文字，或选择一张照片');const {post:created}=await post('/api/moments',{body,mediaIds});featureDialog.close();state.momentDraft=null;if(state.page!=='moments')featurePage('moments','朋友圈',`<button class="icon-button" data-action="compose-moment" aria-label="发布朋友圈">${icon('camera')}</button>`);if(created)updateMoment(created);else await loadMoments();notify('已发布到朋友圈');});}
function renderMomentDraft(){const draft=state.momentDraft,box=featureDialog.querySelector('#moment-draft-photos');if(!draft||!box||draft.stamp!==dialogEpoch)return;box.innerHTML=draft.media.map(m=>`<div><img data-media="${esc(m.id)}" alt="待发布照片" hidden><button type="button" data-action="moment-remove-photo" data-id="${esc(m.id)}" aria-label="移除这张照片">×</button></div>`).join('');featureDialog.querySelector('[name=mediaIds]').value=draft.media.map(m=>m.id).join(',');hydrateMedia(box);}
const momentInput=document.createElement('input');momentInput.type='file';momentInput.accept='image/jpeg,image/png,image/webp';momentInput.multiple=true;momentInput.hidden=true;document.body.append(momentInput);let momentTarget=null;
function pickMomentPhotos(){if(momentUpload||state.uploading){notify('照片正在上传，请稍候');return;}if(!state.momentDraft||state.momentDraft.media.length>=9){notify('最多可以选择 9 张照片');return;}momentTarget={ticket:sessionTicket(),stamp:dialogEpoch,draft:state.momentDraft};momentInput.value='';momentInput.click();}
momentInput.addEventListener('change',async()=>{const target=momentTarget,files=[...momentInput.files||[]];if(!target||!sameSession(target.ticket)||target.stamp!==dialogEpoch||!files.length)return;if(files.length+target.draft.media.length>9){notify('最多可以选择 9 张照片');return;}momentUpload=true;state.uploading=true;const submit=featureDialog.querySelector('[type=submit]');if(submit)submit.disabled=true;try{for(let i=0;i<files.length;i++){assertSession(target.ticket);if(target.stamp!==dialogEpoch||state.momentDraft!==target.draft)return;notify(`正在上传第 ${i+1} 张照片…`);const blob=await compressPhoto(files[i]);assertSession(target.ticket);const {media}=await api('/api/media?purpose=moment',{method:'POST',headers:{'Content-Type':'image/jpeg'},body:blob});assertSession(target.ticket);if(target.stamp!==dialogEpoch||state.momentDraft!==target.draft)return;target.draft.media.push(media);renderMomentDraft();}notify('照片已准备好');}catch(error){if(sameSession(target.ticket))notify(error.message);}finally{if(momentTarget===target){momentUpload=false;if(sameSession(target.ticket))state.uploading=false;}if(submit?.isConnected)submit.disabled=false;}});
function commentMoment(id){openDialog('写评论',`<form><label>评论<textarea name="body" aria-label="评论内容" maxlength="300" rows="3" placeholder="和朋友说点什么…" required></textarea></label>${dialogActions('发送评论')}</form>`);formHandler(async data=>{const {comment}=await post('/api/moments/'+id+'/comments',{body:String(data.get('body')).trim()});const item=state.moments.find(p=>p.id===id);if(item&&comment)item.comments=[...(item.comments||[]),comment];featureDialog.close();renderMoments();notify('评论已发送');});}

async function reminderSettingsDialog(){
  const ticket=sessionTicket(),stamp=dialogEpoch,permissions=await permissionStates();assertSession(ticket);if(stamp!==dialogEpoch)return;
  if(nativeTools.isNative)state.notificationsEnabled=permissions.notificationsActive===true;
  const settings=reminderTools.readSettings(state.user.id),allowed=permissionValue(permissions.notifications)==='granted';
  openDialog('消息提醒',`<p class="hint">有新消息时提醒你；正在阅读的会话、自己发送的消息和免打扰会话不打扰。</p><div class="reminder-options">${[['banner','应用内横幅','点按横幅可进入对应聊天'],['sound','应用内提示音','遵循手机音量与勿扰设置'],['vibration','应用内振动','需设备支持振动']].map(([key,label,help])=>`<label class="toggle-row"><span><b>${label}</b><small>${help}</small></span><input type="checkbox" name="reminder-${key}" data-reminder="${key}" ${settings[key]?'checked':''} aria-label="${label}"></label>`).join('')}</div><button class="button secondary full-width" data-action="test-reminder">试一下提醒</button><h3 class="setting-title">${nativeTools.isNative?'安卓后台通知':'网页通知'}</h3><p class="hint">通知权限：${allowed?'已允许':'尚未允许'} · ${state.notificationsEnabled?'提醒已开启':'提醒未开启'}</p><button class="button full-width" data-action="toggle-notifications" data-value="${state.notificationsEnabled?'false':'true'}">${state.notificationsEnabled?'关闭后台消息提醒':nativeTools.isNative?'开启后台消息提醒':'开启网页消息提醒'}</button>${nativeTools.isNative?`<button class="text-button reminder-system" data-action="system-settings">系统通知设置</button><p class="hint background-limit-note">开启后可在后台接收系统通知，后台提示音与振动由系统通知设置控制。每次最长 5 小时；Android 15 每 24 小时后台同步累计最多 6 小时，系统停止后需重新开启，省电和强行停止会影响提醒。</p>`:'<p class="hint">网页通知需要保持页面打开，关闭浏览器后无法提醒。</p>'}`);
  featureDialog.dataset.section='reminders';
  featureDialog.querySelectorAll('[data-reminder]').forEach(input=>input.addEventListener('change',()=>{if(!sameSession(ticket))return;const next=reminderTools.readSettings(state.user.id);next[input.dataset.reminder]=input.checked;try{reminderTools.writeSettings(state.user.id,next);}catch{input.checked=!input.checked;notify('设置未能保存，请重试');}}));
}
function permissionValue(value){const v=value?.status??value?.state??value?.granted??value;if(v===true||['granted','authorized','allowed'].includes(v))return 'granted';if(v===false||['denied','blocked','restricted','never_ask_again'].includes(v))return 'denied';if(['unsupported','unavailable'].includes(v))return 'unsupported';return 'prompt';}
async function permissionStates(){if(nativeTools.isNative)return await nativeTools.getPermissionState();const result={camera:'prompt',microphone:'prompt',location:'prompt',notifications:window.Notification?Notification.permission:'unsupported'};for(const name of ['camera','microphone','geolocation']){try{result[name==='geolocation'?'location':name]=(await navigator.permissions.query({name})).state;}catch{}}return result;}
async function permissionsDialog(){const ticket=sessionTicket(),stamp=dialogEpoch,permissions=await permissionStates();assertSession(ticket);if(stamp!==dialogEpoch)return;if(nativeTools.isNative&&typeof permissions.notificationsActive==='boolean')state.notificationsEnabled=permissions.notificationsActive;const labels={camera:['相机','拍照、扫一扫和视频通话'],microphone:['麦克风','语音消息与语音通话'],location:['定位','分享当前位置'],notifications:['通知','接收新消息提醒']};openDialog('权限与消息提醒',`<p class="hint">在使用对应功能时才申请权限，拒绝后仍可文字聊天。</p><div class="permission-list">${Object.entries(labels).map(([name,[label,help]])=>{const status=permissionValue(permissions?.[name]);return `<div class="permission-row"><div><b>${label}</b><small>${help}</small></div><span class="permission-status ${status}">${{granted:'已允许',denied:'未允许',prompt:'尚未设置',unsupported:'不支持'}[status]}</span>${status!=='granted'&&status!=='unsupported'?`<button class="text-button" data-action="request-permission" data-name="${name}">允许</button>`:''}</div>`;}).join('')}</div><p class="hint">照片、文件与手机联系人会在你选择时读取。</p>${nativeTools.isNative?`<button class="button secondary full-width" data-action="system-settings">打开系统设置</button><button class="button full-width" data-action="toggle-notifications" data-value="${state.notificationsEnabled?'false':'true'}">${state.notificationsEnabled?'关闭后台消息提醒':'开启后台消息提醒'}</button><p class="hint background-limit-note">后台提醒有运行时限。Android 15 的后台同步（dataSync）每 24 小时累计最多 6 小时；小紫在 每次最长运行 5 小时，系统停止后需回到这里手动重新开启。省电或强行停止也会影响提醒。</p>`:`<button class="button secondary full-width" data-action="request-permission" data-name="notifications" ${!window.Notification?'disabled':''}>开启网页消息提醒</button><p class="hint">网页保持打开时可以显示提醒。</p>`}`);featureDialog.dataset.section='permissions';}
async function requestCapability(name){const ticket=sessionTicket(),stamp=dialogEpoch;if(!['camera','microphone','notifications','location'].includes(name))return;if(name==='notifications'){try{await setNotifications(true);}finally{if(sameSession(ticket)&&sameDialog(stamp))await permissionsDialog().catch(()=>{});}return;}if(nativeTools.isNative){await nativeTools.requestPermission(name);}else if(name==='camera'||name==='microphone'){if(!navigator.mediaDevices?.getUserMedia)throw Error('当前设备不支持这项能力');try{const stream=await navigator.mediaDevices.getUserMedia({audio:name==='microphone',video:name==='camera'});stream.getTracks().forEach(t=>t.stop());}catch{throw Error('权限未获允许，可在浏览器的站点设置中修改');}}else await new Promise((resolve,reject)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(resolve,()=>reject(Error('定位未获允许或暂时无法取得')),{timeout:15000}):reject(Error('当前设备不支持定位')));assertSession(ticket);if(sameDialog(stamp))await permissionsDialog();}
async function syncNotificationState(){const ticket=sessionTicket();if(!nativeTools.isNative)return null;const permissions=await nativeTools.getPermissionState();assertSession(ticket);state.notificationsEnabled=permissions.notificationsActive===true;localStorage.setItem('ichat.notifications.'+state.user.id,state.notificationsEnabled?'1':'0');return permissions;}
async function setNotifications(enabled){
  const ticket=sessionTicket();if(nativeTools.isNative){
    if(enabled){const permission=await nativeTools.requestPermission('notifications');assertSession(ticket);if(permissionValue(permission?.notifications)!=='granted')throw Error('通知未获允许，请在系统设置中开启');const started=await nativeTools.startNotifications({base:apiBase,token:ticket.token});assertSession(ticket);if(started?.notificationsActive!==true)throw Error('后台提醒尚未开启，请在应用前台重试');}
    else await nativeTools.stopNotifications();
  }else{if(!window.Notification)throw Error('当前浏览器不支持消息提醒');if(enabled&&await Notification.requestPermission()!=='granted')throw Error('通知未获允许，仍可正常聊天');}
  assertSession(ticket);state.notificationsEnabled=enabled;localStorage.setItem('ichat.notifications.'+state.user.id,enabled?'1':'0');notify(enabled?(nativeTools.isNative?'后台提醒已开启，每次最长 5 小时':'网页消息提醒已开启'):'消息提醒已关闭');
}
function showBrowserNotification(data){if(nativeTools.isNative||!state.notificationsEnabled||!window.Notification||Notification.permission!=='granted'||document.visibilityState==='visible'||data.conversation?.muted||data.message?.senderId===state.user?.id)return;try{const ticket=sessionTicket(),n=new Notification(chatTitle(data.conversation),{body:messageSummary(data.message),tag:data.conversation.id});n.onclick=()=>{window.focus();if(sameSession(ticket))openConversation(data.conversation.id);n.close();};}catch{}}
async function devicesDialog(){const ticket=sessionTicket(),stamp=dialogEpoch,{sessions}=await api('/api/sessions');assertSession(ticket);if(stamp!==dialogEpoch)return;openDialog('登录设备',`<p class="hint">可以退出其他设备的登录状态。</p><div class="device-list">${sessions.map(s=>`<div class="device-row">${icon('device')}<span><b>${esc(s.label||'小紫在 设备')}</b><small>${s.current?'当前设备 · ':''}最近使用 ${day(s.lastSeenAt||s.createdAt)} ${time(s.lastSeenAt||s.createdAt)}</small></span>${s.current?'<span class="pill">本机</span>':`<button class="text-button danger-text" data-action="revoke-device" data-id="${esc(s.id)}" data-name="${esc(s.label||'这台设备')}">退出</button>`}</div>`).join('')}</div>`);}
async function pickPhoneContact(){const ticket=sessionTicket(),stamp=dialogEpoch;let result;if(nativeTools.isNative)result=await nativeTools.pickContact();else if(navigator.contacts?.select){const selected=await navigator.contacts.select(['name','tel'],{multiple:false});result={name:selected[0]?.name?.[0],phone:selected[0]?.tel?.[0]};}else throw Error('请在手机应用中选择联系人，或手动输入手机号');assertSession(ticket);if(stamp!==dialogEpoch)return;const phone=result?.phone||result?.tel?.[0]||result?.phoneNumber;if(!phone)return;addFriendDialog(String(phone).replace(/[\s()-]/g,''));}
document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-action]');if(!target||target.disabled)return;event.preventDefault();const action=target.dataset.action;
  try{
    if(action==='auth-mode'){state.authMode=target.dataset.mode;renderLogin();}
    else if(action==='connection')showConnection();
    else if(action==='demo'){saveSession(await post('/api/demo/login',{username:target.dataset.identity,deviceName:deviceLabel()}));await startSession();}
    else if(action==='nav'){if(!closeFeature())return;dialogEpoch++;pageEpoch++;saveComposerDraft();state.tab=target.dataset.tab;state.query='';state.page=null;state.activeId=null;state.messages=[];state.replyTo=null;document.querySelector('.app-shell')?.classList.remove('chat-open');if(state.tab==='contacts')await relationships();renderSidebar();renderEmpty();}
    else if(action==='open-chat'){if(!closeFeature())return;await openConversation(target.dataset.id);}
    else if(action==='open-contact'){if(!closeFeature())return;await openContact(target.dataset.id);}
    else if(action==='back')handleBack();
    else if(action==='new-menu')newMenu();
    else if(action==='add-friend')addFriendDialog();
    else if(action==='request-by-account')addFriendDialog(target.dataset.username);
    else if(action==='phone-contact')await pickPhoneContact();
    else if(action==='friend-requests')await requestsDialog();
    else if(action==='respond-friend'){const stamp=dialogEpoch;target.disabled=true;await post('/api/friend-requests/'+target.dataset.id+'/respond',{action:target.dataset.answer});if(sameDialog(stamp))await requestsDialog();notify(target.dataset.answer==='accept'?'已成为好友':'已拒绝申请');}
    else if(action==='create-group')await createGroupDialog();
    else if(action==='group-info')await groupInfo();
    else if(action==='invite-members')await inviteDialog(target.dataset.group);
    else if(action==='edit-group')await editGroupDialog(target.dataset.group);
    else if(action==='group-alias')await groupAliasDialog(target.dataset.group);
    else if(action==='group-admin'){const stamp=dialogEpoch;target.disabled=true;await post('/api/groups/'+target.dataset.group+'/admin',{userId:target.dataset.id,enabled:target.dataset.enabled==='true'});await refreshConversations();if(sameDialog(stamp))await groupInfo(target.dataset.group);notify('管理员设置已更新');}
    else if(action==='group-transfer'){const group=target.dataset.group,id=target.dataset.id;confirmDialog('转让群主','确认把群主身份转让给 '+target.dataset.name+'？转让后你将成为普通成员。',async()=>{await post('/api/groups/'+group+'/transfer',{userId:id});await refreshConversations();notify('群主已转让');});}
    else if(action==='dissolve-group'){const id=target.dataset.group;confirmDialog('解散群聊','解散后，所有成员将无法继续访问这个群聊。确认解散？',async()=>{await post('/api/groups/'+id+'/dissolve');await refreshConversations();notify('群聊已解散');});}
    else if(action==='remove-member'){const group=target.dataset.group,id=target.dataset.id;confirmDialog('移出群成员','确认将 '+target.dataset.name+' 移出群聊？',async()=>{await post('/api/groups/'+group+'/remove',{userId:id});await refreshConversations();notify('成员已移出');});}
    else if(action==='leave-group'){const id=target.dataset.group;confirmDialog('退出群聊','退出后将不能继续读取本群消息；群主退出时会把群主身份转交给其他成员。',async()=>{await post('/api/groups/'+id+'/leave');await refreshConversations();notify('已退出群聊');});}
    else if(action==='contact-info')await contactInfo();
    else if(action==='contact-details')await contactDetails(target.dataset.id);
    else if(action==='edit-remark')await remarkDialog(target.dataset.id);
    else if(action==='contact-setting'){const id=target.dataset.id,key=target.dataset.key,value=target.dataset.value==='true';if(key==='blocked'&&value)confirmDialog('加入黑名单','加入后，双方将无法发起新的私聊和通话。',()=>contactSetting(id,key,value));else await contactSetting(id,key,value);}
    else if(action==='blocked-list')await blockedList();
    else if(action==='unblock-contact'){const stamp=dialogEpoch;target.disabled=true;await post('/api/contacts/'+target.dataset.id+'/settings',{blocked:false});await relationships();if(sameDialog(stamp))await blockedList();notify('已移出黑名单');}
    else if(action==='remove-friend'){const id=target.dataset.id;confirmDialog('删除好友','确认删除 '+target.dataset.name+'？以后需要重新通过好友申请才能聊天。',async()=>{await post('/api/friends/'+id+'/remove');await Promise.all([relationships(),refreshConversations()]);notify('好友已删除');});}
    else if(action==='edit-profile')profileDialog();
    else if(action==='change-password')passwordDialog();
    else if(action==='avatar-photo')pickPhoto('avatar');
    else if(action==='group-avatar')pickPhoto('group',null,target.dataset.group);
    else if(action==='send-photo'){closeFeature(true);pickPhoto('message',state.activeId);}
    else if(action==='send-camera'){closeFeature(true);pickPhoto('message',state.activeId,null,true);}
    else if(action==='retry-photo')await sendPendingPhoto();
    else if(action==='view-photo')await viewPhoto(target.dataset.id);
    else if(action==='close-modal')closeFeature();
    else if(action==='close-image')imageDialog.close();
    else if(action==='chat-menu')chatMenu();
    else if(action==='chat-settings')await chatSettings(target.dataset.id);
    else if(action==='clear-history'){const id=target.dataset.id;confirmDialog('清空我的聊天记录','只清空自己在这段会话中看到的记录，其他成员的记录会保留。确认继续？',async()=>{await post('/api/conversations/'+id+'/clear');if(state.activeId===id){state.messages=[];state.hasMore=false;state.historyJump=false;state.replyTo=null;renderMessages();renderReplyComposer();saveComposerDraft();}await refreshConversations();notify('我的聊天记录已清空');});}
    else if(action==='chat-search')chatSearch(target.dataset.id);
    else if(action==='search-result')await jumpToMessage(target.dataset.id,target.dataset.conversation);
    else if(action==='jump-reply')await jumpToMessage(target.dataset.id);
    else if(action==='latest')await latestMessages();
    else if(action==='message-actions')messageActions(target.dataset.id);
    else if(action==='reply-message'){const m=sourceMessage(target.dataset.id);if(m){state.replyTo=m;saveComposerDraft();renderReplyComposer();closeFeature(true);document.querySelector('#message-input')?.focus();}}
    else if(action==='cancel-reply'){state.replyTo=null;saveComposerDraft();renderReplyComposer();}
    else if(action==='forward-message')forwardDialog(target.dataset.id);
    else if(action==='favorite-message'){const stamp=dialogEpoch;target.disabled=true;await post('/api/favorites',{messageId:target.dataset.id});if(sameDialog(stamp))closeFeature(true);notify('已加入我的收藏');}
    else if(action==='recall-message'){const stamp=dialogEpoch;target.disabled=true;const {message}=await post('/api/messages/'+target.dataset.id+'/recall');if(message&&state.activeId===message.conversationId){mergeMessages([message]);renderMessages(false);}if(sameDialog(stamp))closeFeature(true);await refreshConversations();notify('消息已撤回');}
    else if(action==='hide-message'){const stamp=dialogEpoch;target.disabled=true;const id=target.dataset.id;await post('/api/messages/'+id+'/hide');state.messages=state.messages.filter(m=>m.id!==id);renderMessages(false);if(sameDialog(stamp))closeFeature(true);await refreshConversations();notify('已从我的记录隐藏');}
    else if(action==='attachment-menu')attachmentMenu();
    else if(action==='send-file'){closeFeature(true);pickFile();}
    else if(action==='download-file'){target.disabled=true;await downloadFile(target.dataset.id,target.dataset.name);}
    else if(action==='send-location')await sendLocation();
    else if(action==='view-location')viewLocation(target.dataset.lat,target.dataset.lon,target.dataset.label);
    else if(action==='send-contact')contactCardDialog();
    else if(action==='record-voice')recordVoiceDialog();
    else if(action==='voice-start')await beginVoiceRecording();
    else if(action==='voice-stop')stopVoiceRecording();
    else if(action==='voice-send')await sendVoice();
    else if(action==='voice-redo'){const targetVoice=voiceSession;if(targetVoice){const {ticket,conversationId,replyToId}=targetVoice;disposeVoice();recordVoiceDialog({ticket,conversationId,replyToId});}}
    else if(action==='retry-attachment'){target.disabled=true;await sendPendingRich();}
    else if(action==='cancel-attachment'){state.pendingRich=null;const row=document.querySelector('.attachment-retry');if(row)row.hidden=true;}
    else if(action==='call-audio'||action==='call-video'){const c=active();if(c&&!isGroup(c)){closeFeature(true);await calls.start(c.partner,action==='call-video'?'video':'audio');}}
    else if(action==='favorites')await favoritesPage();
    else if(action==='remove-favorite'){target.disabled=true;await post('/api/favorites/'+target.dataset.id+'/remove');state.favorites=state.favorites.filter(f=>f.id!==target.dataset.id);renderFavorites();notify('收藏已移除');}
    else if(action==='moments'){closeFeature(true);await loadMoments();}
    else if(action==='refresh-moments')await loadMoments();
    else if(action==='older-moments'){target.disabled=true;await loadMoments(true);}
    else if(action==='compose-moment')momentComposer();
    else if(action==='moment-add-photos')pickMomentPhotos();
    else if(action==='moment-remove-photo'){if(momentUpload){notify('照片正在上传，请稍候');return;}if(state.momentDraft){state.momentDraft.media=state.momentDraft.media.filter(m=>m.id!==target.dataset.id);renderMomentDraft();}}
    else if(action==='like-moment'){target.disabled=true;const current=state.moments.find(p=>p.id===target.dataset.id);if(current){const {post:changed}=await post('/api/moments/'+current.id+'/like',{liked:!current.likedByMe});updateMoment(changed);}}
    else if(action==='comment-moment')commentMoment(target.dataset.id);
    else if(action==='delete-moment'){const id=target.dataset.id;confirmDialog('删除朋友圈','确认删除这条动态及其评论和点赞？',async()=>{await post('/api/moments/'+id+'/remove');state.moments=state.moments.filter(p=>p.id!==id);renderMoments();notify('动态已删除');});}
    else if(action==='delete-comment'){const id=target.dataset.id,postId=target.dataset.post;confirmDialog('删除评论','确认删除这条评论？',async()=>{await post('/api/moment-comments/'+id+'/remove');const p=state.moments.find(p=>p.id===postId);if(p)p.comments=p.comments.filter(c=>c.id!==id);renderMoments();notify('评论已删除');});}
    else if(action==='my-code')showMyCode(state.user,{notify});
    else if(action==='scan-code'){const ticket=sessionTicket();await scanCode({notify,onUser:username=>{if(sameSession(ticket))addFriendDialog(username);}});}
    else if(action==='devices')await devicesDialog();
    else if(action==='revoke-device'){const id=target.dataset.id;confirmDialog('退出其他设备','确认退出 '+target.dataset.name+' 的登录状态？',async()=>{await post('/api/sessions/'+id+'/revoke');notify('已退出这台设备');});}
    else if(action==='permissions')await permissionsDialog();
    else if(action==='reminder-settings')await reminderSettingsDialog();
    else if(action==='test-reminder'){await reminderTools.play(reminderTools.readSettings(state.user.id),{test:true});notify('已试播提醒；提示音受系统音量和勿扰设置影响');}
    else if(action==='request-permission')await requestCapability(target.dataset.name);
    else if(action==='system-settings')await nativeTools.openSystemSettings();
    else if(action==='toggle-notifications'){const stamp=dialogEpoch,section=featureDialog.dataset.section;target.disabled=true;await setNotifications(target.dataset.value==='true');if(sameDialog(stamp))await(section==='reminders'?reminderSettingsDialog():permissionsDialog());}
    else if(action==='logout'){if(!closeFeature())return;const revoke=post('/api/logout');logoutLocally();revoke.catch(()=>{});}
    else if(action==='older')await loadOlder();
    else if(action==='emoji'){const picker=document.querySelector('#emoji-picker');picker.hidden=!picker.hidden;picker.innerHTML=picker.hidden?'':['😊','🙌','✨','👍','☕','💚'].map(e=>`<button type="button" data-action="insert-emoji" data-emoji="${e}" aria-label="表情${e}">${e}</button>`).join('');}
    else if(action==='insert-emoji'){const input=document.querySelector('#message-input');if(input.value.length<1998)input.value+=target.dataset.emoji;saveComposerDraft();input.focus();}
  }catch(error){notify(error.message||'操作暂时失败，请重试');}finally{if(target.isConnected)target.disabled=false;}
});
document.querySelector('#cancel-connection').addEventListener('click',()=>document.querySelector('#connection-dialog').close());
document.querySelector('#connection-form').addEventListener('submit',async e=>{e.preventDefault();try{const url=new URL(document.querySelector('#server-url').value.trim());if(!['http:','https:'].includes(url.protocol)||url.username||url.password||url.search||url.hash||url.pathname!=='/')throw Error('请填写完整服务器地址，不包含用户名、密码或路径');const response=await fetchWithin(url.origin+'/api/health',{},10000),health=await response.json();if(!response.ok||health.app!=='iChat')throw Error('这个地址不是可用的小紫在服务器');localStorage.setItem('ichat.server',url.origin);localStorage.removeItem(sessionKey);state.socket?.close();location.reload();}catch(error){document.querySelector('#connection-error').textContent=error.message;}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible'&&voiceSession?.recording)stopVoiceRecording();if(document.visibilityState==='visible'&&state.token){if(nativeTools.isNative)syncNotificationState().catch(()=>{});syncSession().catch(()=>{});if(state.activeId)markRead(state.activeId);}});
async function init(){renderLogin();try{const saved=JSON.parse(localStorage.getItem(sessionKey)||'null');if(saved?.token&&saved?.user){saveSession(saved);}}catch{localStorage.removeItem(sessionKey);}try{state.demo=(await api('/api/health')).demo;}catch{}if(state.token){try{state.user=(await api('/api/me')).user;await startSession();return;}catch(error){if(error.status===401)logoutLocally();else notify(error.message);}}if(demoIdentity&&state.demo){saveSession(await post('/api/demo/login',{username:demoIdentity}));await startSession();return;}if(!Array.from(document.querySelectorAll('#auth-form input')).some(i=>i.value))renderLogin();if(native&&!apiBase)showConnection();}
init().catch(()=>notify('启动暂时失败，请重新打开应用'));
